INSERT INTO r VALUES('1.1','abcxyz' LIKE 'ABC%'),('1.1b','abc%xyz' LIKE 'ABC\%x%' ESCAPE '\'); PRAGMA case_sensitive_like=1; INSERT INTO r VALUES('1.3','abcxyz' LIKE 'ABC%'),('1.3b','abc%xyz' LIKE 'ABC\%X%' ESCAPE '\'),('1.4','ABCxyz' LIKE 'ABC%'),('1.4b','ABC%xyz' LIKE 'ABC\%x%' ESCAPE '\'); PRAGMA case_sensitive_like=0; INSERT INTO r VALUES('1.6','abcxyz' LIKE 'ABC%'),('1.6b','abc%xyz' LIKE 'ABC\%X%' ESCAPE '\'),('1.7','ABCxyz' LIKE 'ABC%'),('1.7b','ABC%xyz' LIKE 'ABC\%X%' ESCAPE '\');